mapper.select:
SELECT a.log_id,
       a.obj_type,
       a.obj_id,
       COALESCE(b.scene_name, c.flow_name) AS obj_name,
       a.context_id,
       b.scene_type,
       a.start_time,
       a.time_spent,
       a.log_status,
       a.fail_msg,
       a.user_id,
       d.real_name AS user_name
FROM bt_flow_run_log a
LEFT JOIN bt_bot_scene b ON b.tenant_id = a.tenant_id AND b.scene_id = a.obj_id AND a.obj_type = 'scene'
LEFT JOIN bt_skill_flow c ON c.tenant_id = a.tenant_id AND c.flow_id = a.obj_id AND a.obj_type = 'flow'
LEFT JOIN bt_user d ON d.user_id = a.user_id
WHERE a.tenant_id = #{query.tenantId}

  AND a.obj_type = #{query.objType}

    AND a.obj_id = #{query.sceneId}



  AND a.obj_type = #{query.objType}

    AND a.obj_id = #{query.flowId}



  AND a.user_id = #{query.userId}


  AND a.start_time >= #{query.minStartTime}


  AND a.start_time <= #{query.maxStartTime}


  AND a.log_status = #{query.logStatus}


  AND a.context_id = #{query.contextId}

ORDER BY a.start_time DESC

mapper.delete:

DELETE
FROM bt_flow_run_log
WHERE log_id IN (
    SELECT log_id
    FROM bt_flow_run_log
    WHERE start_time < #{maxDate}
     #{limit}
   )
